    protected ConsentRow() {}

    ConsentRow(String consentId, String consentText, Instant givenAt) {
      this.consentId = consentId;
      this.consentText = consentText;
      this.givenAt = givenAt;
    }

    String consentId() {
      return consentId;
    }

    String consentText() {
      return consentText;
    }

    Instant givenAt() {
      return givenAt;
    }
  }
}

