package si.konferenca.registration.persistence;

import java.util.List;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Component;
import si.konferenca.registration.application.DuplicateEmailException;
import si.konferenca.registration.application.RegistrationStore;
import si.konferenca.registration.domain.AcceptedRegistration;
import si.konferenca.registration.domain.AcceptedRegistration.GivenConsent;
import si.konferenca.registration.domain.AcceptedRegistration.Participant;
import si.konferenca.registration.domain.AcceptedRegistration.SelectedOption;

/** PostgreSQL adapter of {@link RegistrationStore} (US-005, US-008). */
@Component
class JpaRegistrationStore implements RegistrationStore {

  private static final String UNIQUE_EMAIL = "uq_registration_email_normalized";

  private final RegistrationRepository repository;

  JpaRegistrationStore(RegistrationRepository repository) {
    this.repository = repository;
  }

  @Override
  public boolean existsByNormalizedEmail(String normalizedEmail) {
    return repository.existsByEmailNormalized(normalizedEmail);
  }

  @Override
  public void insert(AcceptedRegistration registration) {
    Participant p = registration.participant();
    RegistrationEntity entity =
        new RegistrationEntity(
            registration.reference(),
            registration.type(),
            p.firstName(),
            p.lastName(),
            p.email(),
            registration.normalizedEmail(),
            p.organization(),
            p.studyInstitution(),
            p.studyProgramme(),
            p.studentId(),
            registration.submittedAt());
    for (SelectedOption option : registration.options()) {
      entity
          .options()
          .add(new RegistrationEntity.OptionRow(option.id(), option.name(), option.category()));
    }
    for (GivenConsent consent : registration.consents()) {
      entity
          .consents()
          .add(new RegistrationEntity.ConsentRow(consent.id(), consent.text(), consent.givenAt()));
    }
    try {
      repository.saveAndFlush(entity);
    } catch (DataIntegrityViolationException e) {
      if (mentionsUniqueEmail(e)) {
        throw new DuplicateEmailException();
      }
      throw e;
    }
  }

  @Override
  public List<AcceptedRegistration> findAllOrderedBySubmission() {
    return repository.findAllByOrderBySubmittedAtAscIdAsc().stream()
        .map(JpaRegistrationStore::toDomain)
        .toList();
  }

  private static boolean mentionsUniqueEmail(Throwable e) {
    for (Throwable t = e; t != null; t = t.getCause()) {
      if (t.getMessage() != null && t.getMessage().contains(UNIQUE_EMAIL)) {
        return true;
      }
    }
    return false;
  }

  private static AcceptedRegistration toDomain(RegistrationEntity e) {
    return new AcceptedRegistration(
        e.reference(),
        e.submittedAt(),
        e.type(),
        new Participant(
            e.firstName(),
            e.lastName(),
            e.email(),
            e.organization(),
            e.studyInstitution(),
            e.studyProgramme(),
            e.studentId()),
        e.options().stream()
            .map(o -> new SelectedOption(o.optionId(), o.optionName(), o.category()))
            .toList(),
        e.consents().stream()
            .map(c -> new GivenConsent(c.consentId(), c.consentText(), c.givenAt()))
            .toList());
  }
}

package si.konferenca.registration.persistence;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.UUID;
import si.konferenca.registration.application.JsonCopyStore;
import si.konferenca.registration.domain.AcceptedRegistration;

/**
 * Writes {@code registration-<reference>.json} into the configured directory: temp file, fsync,
 * atomic rename; an existing copy is never overwritten (BR-07).
 */
public class FileJsonCopyStore implements JsonCopyStore {

  private final Path directory;

  public FileJsonCopyStore(Path directory) {
    this.directory = directory;
  }

  @Override
  public byte[] write(AcceptedRegistration registration) {
    byte[] content = RegistrationJson.toBytes(registration);
    Path target = file(registration.reference());
    Path temp = null;
    try {
      Files.createDirectories(directory);
      if (Files.exists(target)) {
        throw new FileAlreadyExistsException(target.getFileName().toString());
      }
      temp = Files.createTempFile(directory, ".registration-", ".tmp");
      try (FileChannel channel = FileChannel.open(temp, StandardOpenOption.WRITE)) {
        ByteBuffer buffer = ByteBuffer.wrap(content);
        while (buffer.hasRemaining()) {
          channel.write(buffer);
        }
        channel.force(true);
      }
      Files.move(temp, target, StandardCopyOption.ATOMIC_MOVE);
      return content;
    } catch (IOException e) {
      deleteQuietly(temp);
      throw new UncheckedIOException("JSON copy could not be written", e);
    }
  }

  @Override
  public void delete(UUID reference) {
    deleteQuietly(file(reference));
  }

  private Path file(UUID reference) {
    return directory.resolve("registration-" + reference + ".json");
  }

  private static void deleteQuietly(Path path) {
    if (path == null) {
      return;
    }
    try {
      Files.deleteIfExists(path);
    } catch (IOException e) {
      // nothing more can be done; the copy is orphaned and harmless
    }
  }
}

package si.konferenca.registration.persistence;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import si.konferenca.registration.domain.AcceptedRegistration;
import si.konferenca.registration.domain.AcceptedRegistration.Participant;
import tools.jackson.databind.SerializationFeature;
import tools.jackson.databind.json.JsonMapper;

/** The JSON copy document (contract registration-copy.schema.json, schemaVersion 1), UTF-8. */
final class RegistrationJson {

  private static final JsonMapper JSON =
      JsonMapper.builder().enable(SerializationFeature.INDENT_OUTPUT).build();

  private RegistrationJson() {}

  static byte[] toBytes(AcceptedRegistration r) {
    Map<String, Object> document = new LinkedHashMap<>();
    document.put("schemaVersion", 1);
    document.put("reference", r.reference().toString());
    document.put("submittedAt", r.submittedAt().toString());
    document.put("type", r.type().name());
    document.put("participant", participant(r.participant()));
    document.put(
        "options",
        r.options().stream()
            .map(
                o ->
                    ordered(
                        List.of("id", o.id(), "name", o.name(), "category", o.category().name())))
            .toList());
    document.put(
        "consents",
        r.consents().stream()
            .map(
                c ->
                    ordered(
                        List.of("id", c.id(), "text", c.text(), "givenAt", c.givenAt().toString())))
            .toList());
    return JSON.writeValueAsBytes(document);
  }

  private static Map<String, Object> participant(Participant p) {
    Map<String, Object> map = new LinkedHashMap<>();
    map.put("firstName", p.firstName());
    map.put("lastName", p.lastName());
    map.put("email", p.email());
    putIfPresent(map, "organization", p.organization());
    putIfPresent(map, "studyInstitution", p.studyInstitution());
    putIfPresent(map, "studyProgramme", p.studyProgramme());
    putIfPresent(map, "studentId", p.studentId());
    return map;
  }

  private static void putIfPresent(Map<String, Object> map, String key, String value) {
    if (value != null) {
      map.put(key, value);
    }
  }

  private static Map<String, Object> ordered(List<String> keysAndValues) {
    Map<String, Object> map = new LinkedHashMap<>();
    for (int i = 0; i < keysAndValues.size(); i += 2) {
      map.put(keysAndValues.get(i), keysAndValues.get(i + 1));
    }
    return map;
  }
}

