package si.konferenca.registration.infrastructure;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.api.Test;
import si.konferenca.registration.domain.OptionCatalog;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.RegistrationType;

class OptionCatalogLoaderTest {

  private static final String CONSENTS =
      "\"consents\": [{\"id\": \"data\", \"text\": \" Soglasje \", \"mandatory\": true}]";

  private static OptionCatalog load(String json) {
    return new OptionCatalogLoader()
        .load(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)), "test.json");
  }

  private static String options(String option) {
    return "{\"options\": [" + option + "], " + CONSENTS + "}";
  }

  @Test
  void loadsOptionsAndConsents() {
    OptionCatalog catalog =
        load(
            options(
                "{\"id\": \"ws-a\", \"name\": \" Delavnica \", \"category\": \"WORKSHOP\","
                    + " \"active\": false, \"audience\": [\"STUDENT\"]}"));

    assertThat(catalog.options()).hasSize(1);
    var option = catalog.options().get(0);
    assertThat(option.name()).isEqualTo("Delavnica");
    assertThat(option.category()).isEqualTo(OptionCategory.WORKSHOP);
    assertThat(option.active()).isFalse();
    assertThat(option.audience()).containsExactly(RegistrationType.STUDENT);
    assertThat(catalog.consents().get(0).text()).isEqualTo("Soglasje");
    assertThat(catalog.consents().get(0).mandatory()).isTrue();
  }

  @Test
  void audienceDefaultsToBoth() {
    OptionCatalog catalog =
        load(options("{\"id\": \"m\", \"name\": \"M\", \"category\": \"MEAL\", \"active\": true}"));

    assertThat(catalog.options().get(0).audience())
        .containsExactlyInAnyOrder(RegistrationType.values());
  }

  @ParameterizedTest
  @CsvSource(
      delimiter = '|',
      value = {
        "not json|not valid JSON",
        "[]|top level must be an object",
        "{\"options\": [], \"consents\": [], \"x\": 1}|unknown field 'x'",
        "{\"consents\": []}|'options' must be a list",
        "{\"options\": [], \"consents\": {}}|'consents' must be a list",
        "{\"options\": [1], \"consents\": []}|option #0 must be an object",
        "{\"options\": [{\"id\": \"Bad Id\"}], \"consents\": []}|option #0 has a missing or invalid 'id'",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\"}], \"consents\": []}|option 'a': 'active' must be true or false",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"active\": true, \"audience\": []}], \"consents\": []}|option 'a': 'audience' must be a non-empty list",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"active\": true, \"audience\": [1]}], \"consents\": []}|unknown audience '1'",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": 5, \"active\": true}], \"consents\": []}|unknown category '5'",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"meal\", \"active\": true}], \"consents\": []}|unknown category 'meal'",
        "{\"options\": [{\"id\": \"a\", \"name\": \"  \", \"category\": \"MEAL\", \"active\": true}], \"consents\": []}|'name' is missing or empty",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"active\": true, \"price\": 1}], \"consents\": []}|option 'a': unknown field 'price'",
        "{\"options\": [], \"consents\": [{\"id\": \"c\", \"text\": \"T\"}]}|consent 'c': 'mandatory' must be true or false",
        "{\"options\": [], \"consents\": [{\"id\": \"c\", \"text\": \"T\", \"mandatory\": true}, {\"id\": \"c\", \"text\": \"T\", \"mandatory\": true}]}|consent 'c' is defined more than once",
        "{\"options\": [], \"consents\": [{\"id\": \"c\", \"text\": \"\", \"mandatory\": true}]}|consent 'c': 'text' is missing or empty"
      })
  void rejectsInvalidFilesNamingTheProblem(String json, String message) {
    assertThatThrownBy(() -> load(json))
        .isInstanceOf(InvalidOptionsException.class)
        .hasMessageContaining("test.json")
        .hasMessageContaining(message);
  }

  @Test
  void rejectsTooLongName() {
    String json =
        options(
            "{\"id\": \"a\", \"name\": \""
                + "n".repeat(201)
                + "\", \"category\": \"MEAL\", \"active\": true}");

    assertThatThrownBy(() -> load(json)).hasMessageContaining("longer than 200");
  }
}

package si.konferenca.registration.infrastructure;

import java.time.Instant;
import java.util.List;
import java.util.UUID;
import si.konferenca.registration.domain.AcceptedRegistration;
import si.konferenca.registration.domain.AcceptedRegistration.GivenConsent;
import si.konferenca.registration.domain.AcceptedRegistration.Participant;
import si.konferenca.registration.domain.AcceptedRegistration.SelectedOption;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.RegistrationType;

/** Sample accepted registrations for adapter tests. */
final class Registrations {

  static final UUID REFERENCE = UUID.fromString("3f2b8c1e-6a4d-4e2b-9f1a-0c5d7e8f9a10");
  static final Instant AT = Instant.parse("2026-10-11T08:00:00.123Z");

  private Registrations() {}

  static AcceptedRegistration external() {
    return new AcceptedRegistration(
        REFERENCE,
        AT,
        RegistrationType.EXTERNAL,
        new Participant("Čedomir", "Žagar", "c@example.si", "IJS", null, null, null),
        List.of(
            new SelectedOption("ws-ai", "AI", OptionCategory.WORKSHOP),
            new SelectedOption("ws-sec", "Security", OptionCategory.WORKSHOP),
            new SelectedOption("meal", "Lunch", OptionCategory.MEAL)),
        List.of(new GivenConsent("data", "Data", AT)));
  }

  static AcceptedRegistration student() {
    return new AcceptedRegistration(
        REFERENCE,
        AT,
        RegistrationType.STUDENT,
        new Participant("Luka", "Kranjc", "l@example.si", null, "UM", "RIT", "E1"),
        List.of(),
        List.of(new GivenConsent("data", "Data", AT), new GivenConsent("photos", "Photos", AT)));
  }
}

package si.konferenca.registration.infrastructure;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import jakarta.mail.MessagingException;
import jakarta.mail.Session;
import jakarta.mail.internet.MimeMessage;
import jakarta.mail.internet.MimeMultipart;
import java.io.IOException;
import java.util.List;
import java.util.Properties;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.mail.javamail.JavaMailSender;

class MailNotifierTest {

  private final JavaMailSender sender = mock(JavaMailSender.class);
  private final MailNotifier notifier =
      new MailNotifier(
          sender,
          new MailNotifier.MailSettings(
              "from@konf.si", "Konf\r\n2026", List.of(" o1@konf.si ", "", "o2@konf.si")));

  private MimeMessage sent() {
    ArgumentCaptor<MimeMessage> captor = ArgumentCaptor.forClass(MimeMessage.class);
    verify(sender).send(captor.capture());
    return captor.getValue();
  }

  @Test
  void settingsCleanConfigurationValues() {
    MailNotifier.MailSettings settings =
        new MailNotifier.MailSettings("f", "A\nB", List.of(" x ", " "));

    assertThat(settings.conferenceName()).isEqualTo("A B");
    assertThat(settings.organizerEmails()).containsExactly("x");
  }

  @Test
  void participantConfirmationIsPlainText() throws Exception {
    when(sender.createMimeMessage()).thenReturn(new MimeMessage(Session.getInstance(new Properties())));

    notifier.sendParticipantConfirmation(Registrations.external());

    MimeMessage message = sent();
    assertThat(message.getFrom()[0].toString()).isEqualTo("from@konf.si");
    assertThat(message.getAllRecipients()).extracting(Object::toString).containsExactly("c@example.si");
    assertThat(message.getSubject())
        .isEqualTo("Konf  2026 – registration confirmed (" + Registrations.REFERENCE + ")");
    assertThat(message.getContentType()).startsWith("text/plain");
    assertThat((String) message.getContent())
        .contains("Dear Čedomir Žagar,", "Registration type: External participant")
        .contains("- AI (Workshop)", "- Lunch (Meal)");
  }

  @Test
  void organizerNotificationAttachesTheCopy() throws Exception {
    when(sender.createMimeMessage()).thenReturn(new MimeMessage(Session.getInstance(new Properties())));
    byte[] copy = "{\"x\":1}".getBytes();

    notifier.sendOrganizerNotification(Registrations.student(), copy);

    MimeMessage message = sent();
    message.saveChanges();
    assertThat(message.getAllRecipients())
        .extracting(Object::toString)
        .containsExactly("o1@konf.si", "o2@konf.si");
    assertThat(message.getSubject()).isEqualTo("Konf  2026 – new registration " + Registrations.REFERENCE);
    MimeMultipart mixed = (MimeMultipart) message.getContent();
    assertThat(attachment(mixed).getFileName()).isEqualTo("registration-" + Registrations.REFERENCE + ".json");
    assertThat(attachment(mixed).getInputStream().readAllBytes()).isEqualTo(copy);
  }

  private static jakarta.mail.BodyPart attachment(MimeMultipart mixed) throws MessagingException {
    return mixed.getBodyPart(mixed.getCount() - 1);
  }

  @Test
  void composeFailureBecomesIllegalState() throws Exception {
    MimeMessage broken = mock(MimeMessage.class);
    when(sender.createMimeMessage()).thenReturn(broken);
    doThrow(new MessagingException("x")).when(broken).setFrom(any(jakarta.mail.Address.class));

    assertThatThrownBy(() -> notifier.sendParticipantConfirmation(Registrations.external()))
        .isInstanceOf(IllegalStateException.class);
    assertThatThrownBy(() -> notifier.sendOrganizerNotification(Registrations.external(), new byte[0]))
        .isInstanceOf(IllegalStateException.class);
  }

  @Test
  void organizerTextListsRegistrationData() throws IOException {
    String text = MailTexts.organizerNotification(Registrations.student());

    assertThat(text)
        .contains("New registration " + Registrations.REFERENCE + " submitted at 2026-10-11T08:00:00.123Z.")
        .contains("Type: Student", "First name: Luka", "Last name: Kranjc", "Email: l@example.si")
        .contains("Study institution: UM", "Study programme: RIT", "Student ID: E1")
        .contains("Workshops: -", "Events: -", "Meals: -", "Other activities: -")
        .contains("- data given at 2026-10-11T08:00:00.123Z", "- photos given at")
        .doesNotContain("Organization");
    assertThat(MailTexts.organizerNotification(Registrations.external()))
        .contains("Organization / institution: IJS", "Workshops: AI, Security", "Meals: Lunch")
        .doesNotContain("Study institution");
  }

  @Test
  void participantTextWithoutOptions() {
    assertThat(MailTexts.participantConfirmation(Registrations.student(), "Konf"))
        .contains("your registration for Konf has been received.", "Registration type: Student", "- none");
  }
}

