package si.konferenca.registration.persistence;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import si.konferenca.registration.domain.AcceptedRegistration;
import si.konferenca.registration.domain.AcceptedRegistration.GivenConsent;
import si.konferenca.registration.domain.AcceptedRegistration.Participant;
import si.konferenca.registration.domain.AcceptedRegistration.SelectedOption;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.RegistrationType;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

class FileJsonCopyStoreTest {

  private static final Instant AT = Instant.parse("2026-10-11T08:00:00.123Z");

  @TempDir Path dir;

  private static AcceptedRegistration student() {
    return new AcceptedRegistration(
        UUID.randomUUID(),
        AT,
        RegistrationType.STUDENT,
        new Participant("Luka", "Kranjc", "l@example.si", null, "UM", "Računalništvo", "E1"),
        List.of(new SelectedOption("ev", "Večer", OptionCategory.EVENT)),
        List.of(new GivenConsent("data", "Soglasje", AT)));
  }

  @Test
  void writesTheContractDocumentAndReturnsItsBytes() throws Exception {
    AcceptedRegistration r = student();
    Path nested = dir.resolve("a/b");

    byte[] written = new FileJsonCopyStore(nested).write(r);

    Path file = nested.resolve("registration-" + r.reference() + ".json");
    assertThat(Files.readAllBytes(file)).isEqualTo(written);
    JsonNode json = JsonMapper.builder().build().readTree(new String(written, StandardCharsets.UTF_8));
    assertThat(json.propertyNames())
        .containsExactly("schemaVersion", "reference", "submittedAt", "type", "participant", "options", "consents");
    assertThat(json.get("schemaVersion").asInt()).isEqualTo(1);
    assertThat(json.get("submittedAt").asString()).isEqualTo("2026-10-11T08:00:00.123Z");
    assertThat(json.get("participant").propertyNames())
        .containsExactly("firstName", "lastName", "email", "studyInstitution", "studyProgramme", "studentId");
    assertThat(json.get("participant").get("studyProgramme").asString()).isEqualTo("Računalništvo");
    assertThat(json.get("options").get(0).propertyNames()).containsExactly("id", "name", "category");
    assertThat(json.get("options").get(0).get("category").asString()).isEqualTo("EVENT");
    assertThat(json.get("consents").get(0).get("givenAt").asString()).isEqualTo("2026-10-11T08:00:00.123Z");
    try (Stream<Path> files = Files.list(nested)) {
      assertThat(files).hasSize(1);
    }
  }

  @Test
  void neverOverwritesAnExistingCopy() throws Exception {
    AcceptedRegistration r = student();
    FileJsonCopyStore store = new FileJsonCopyStore(dir);
    Path file = dir.resolve("registration-" + r.reference() + ".json");
    Files.writeString(file, "original");

    assertThatThrownBy(() -> store.write(r)).isInstanceOf(UncheckedIOException.class);
    assertThat(Files.readString(file)).isEqualTo("original");
    try (Stream<Path> files = Files.list(dir)) {
      assertThat(files).hasSize(1);
    }
  }

  @Test
  void failsWhenTheDirectoryIsAFile() throws Exception {
    Path notADirectory = Files.writeString(dir.resolve("file"), "x");

    assertThatThrownBy(() -> new FileJsonCopyStore(notADirectory).write(student()))
        .isInstanceOf(UncheckedIOException.class)
        .hasMessage("JSON copy could not be written");
  }

  @Test
  void deleteRemovesTheCopyAndIgnoresMissingOnes() {
    AcceptedRegistration r = student();
    FileJsonCopyStore store = new FileJsonCopyStore(dir);
    store.write(r);

    store.delete(r.reference());
    store.delete(r.reference());

    assertThat(dir.resolve("registration-" + r.reference() + ".json")).doesNotExist();
  }

  @Test
  void externalCopyHasOrganizationOnly() {
    AcceptedRegistration r =
        new AcceptedRegistration(
            UUID.randomUUID(),
            AT,
            RegistrationType.EXTERNAL,
            new Participant("A", "B", "a@x.si", "IJS", null, null, null),
            List.of(),
            List.of());

    JsonNode json = JsonMapper.builder().build().readTree(RegistrationJson.toBytes(r));

    assertThat(json.get("participant").propertyNames())
        .containsExactly("firstName", "lastName", "email", "organization");
    assertThat(json.get("options").isEmpty()).isTrue();
  }
}

package si.konferenca.registration.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Duration;
import java.util.List;
import org.junit.jupiter.api.Test;

class StartupGuardTest {

  private static AppProperties properties(
      String environment,
      String username,
      String password,
      List<String> emails,
      boolean httpsOnly,
      String options,
      boolean testMode,
      String siteKey,
      String secretKey,
      String cors) {
    return new AppProperties(
        environment,
        "Konf",
        new AppProperties.Mail("from@konf.si"),
        new AppProperties.Organizer(username, password, emails, httpsOnly),
        new AppProperties.Options(options),
        new AppProperties.JsonCopy("/data"),
        new AppProperties.Recaptcha(testMode, siteKey, secretKey, "https://verify"),
        new AppProperties.Cors(cors),
        new AppProperties.RateLimits(
            new AppProperties.Limit(10, Duration.ofMinutes(10)),
            new AppProperties.ExportLimit(20, Duration.ofMinutes(10))),
        new AppProperties.Request(16384));
  }

  private static AppProperties validProduction() {
    return properties(
        "production", "org", "a-password-of-16+", List.of("o@konf.si"), true, "file:/c.json", false, "site", "secret", null);
  }

  @Test
  void validProductionStarts() {
    assertThat(StartupGuard.problems(validProduction())).isEmpty();
    assertThat(StartupGuard.verify(validProduction())).isNotNull();
    assertThat(validProduction().production()).isTrue();
  }

  @Test
  void unsafeProductionIsRefused() {
    AppProperties unsafe =
        properties(
            "production", "org", "a-password-of-16+", List.of("o@konf.si"), false,
            AppProperties.DEFAULT_OPTIONS_LOCATION, true, "", " ", "http://localhost:5173");

    assertThat(StartupGuard.problems(unsafe))
        .containsExactly(
            "reCAPTCHA test mode must be off in production",
            "reCAPTCHA keys (RECAPTCHA_SITE_KEY, RECAPTCHA_SECRET_KEY) are not set",
            "app.options.location must point to the production options file",
            "organizer HTTPS-only access must be on in production",
            "CORS (app.cors.allowed-origin) is for local development only");
    assertThatThrownBy(() -> StartupGuard.verify(unsafe))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageStartingWith("Refusing to start: reCAPTCHA test mode");
  }

  @Test
  void eachMissingKeyAloneIsReported() {
    assertThat(StartupGuard.problems(properties(
            "production", "org", "a-password-of-16+", List.of("o@konf.si"), true, "file:/c.json", false, null, "s", null)))
        .hasSize(1);
    assertThat(StartupGuard.problems(properties(
            "production", "org", "a-password-of-16+", List.of("o@konf.si"), true, "file:/c.json", false, "k", null, null)))
        .hasSize(1);
  }

  @Test
  void localMayUseTestModeAndDefaults() {
    AppProperties local =
        properties(
            "local", "org", "a-password-of-16+", List.of("o@konf.si"), false,
            AppProperties.DEFAULT_OPTIONS_LOCATION, true, null, null, "http://localhost:5173");

    assertThat(StartupGuard.problems(local)).isEmpty();
    assertThat(local.production()).isFalse();
  }

  @Test
  void organizerSettingsAndEnvironmentAreRequired() {
    AppProperties missing = properties("staging", " ", null, List.of(" "), true, "x", false, "k", "s", null);
    AppProperties shortPassword =
        properties("test", "org", "a".repeat(15), List.of("o@konf.si"), true, "x", false, "k", "s", null);

    assertThat(StartupGuard.problems(missing))
        .containsExactly(
            "app.environment must be production, local or test",
            "organizer username (ORGANIZER_USERNAME) is not set",
            "organizer password (ORGANIZER_PASSWORD) is not set",
            "organizer emails (ORGANIZER_EMAILS) are not set");
    assertThat(StartupGuard.problems(shortPassword))
        .containsExactly("organizer password (ORGANIZER_PASSWORD) is shorter than 16");
    assertThat(
            StartupGuard.problems(
                properties("test", "org", "a".repeat(16), List.of("o@konf.si"), true, "x", false, "k", "s", null)))
        .isEmpty();
  }
}

package si.konferenca.registration.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import jakarta.servlet.http.HttpServletRequest;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockFilterChain;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import si.konferenca.registration.api.PayloadTooLargeException;

class RequestFiltersTest {

  private final AtomicLong clock = new AtomicLong();

  private FixedWindowRateLimiter limiter(int max) {
    return new FixedWindowRateLimiter(max, Duration.ofSeconds(60), clock::get);
  }

  @Test
  void limiterAllowsUpToTheLimitPerKeyAndResetsAfterTheWindow() {
    FixedWindowRateLimiter limiter = limiter(2);

    assertThat(limiter.acquire("a")).isZero();
    assertThat(limiter.acquire("a")).isZero();
    clock.set(Duration.ofSeconds(15).toNanos());
    assertThat(limiter.acquire("a")).isEqualTo(45);
    assertThat(limiter.acquire("b")).isZero();
    clock.set(Duration.ofSeconds(59).toNanos() + 900_000_000L);
    assertThat(limiter.acquire("a")).isEqualTo(1);
    clock.set(Duration.ofSeconds(60).toNanos());
    assertThat(limiter.acquire("a")).isZero();
  }

  @Test
  void limiterCleansUpExpiredWindowsWhenLarge() {
    FixedWindowRateLimiter limiter = limiter(1);
    for (int i = 0; i <= 10_001; i++) {
      limiter.acquire("k" + i);
    }
    clock.set(Duration.ofSeconds(61).toNanos());

    assertThat(limiter.acquire("k0")).isZero();
    assertThat(limiter.acquire("k0")).isPositive();
  }

  private static MockHttpServletResponse run(
      jakarta.servlet.Filter filter, MockHttpServletRequest request) throws Exception {
    MockHttpServletResponse response = new MockHttpServletResponse();
    filter.doFilter(request, response, new MockFilterChain());
    return response;
  }

  @Test
  void rateLimitFilterChoosesTheBucketByPath() throws Exception {
    RateLimitFilter filter = new RateLimitFilter(limiter(1), limiter(1));
    MockHttpServletRequest post = new MockHttpServletRequest("POST", "/api/registrations");
    MockHttpServletRequest export = new MockHttpServletRequest("GET", "/api/export/registrations.xlsx");
    MockHttpServletRequest other = new MockHttpServletRequest("GET", "/api/form-config");
    MockHttpServletRequest getRegistrations = new MockHttpServletRequest("GET", "/api/registrations");

    assertThat(run(filter, post).getStatus()).isEqualTo(200);
    MockHttpServletResponse limited = run(filter, post);
    assertThat(limited.getStatus()).isEqualTo(429);
    assertThat(limited.getHeader("Retry-After")).isEqualTo("60");
    assertThat(limited.getContentAsString()).contains("\"error\":\"TOO_MANY_REQUESTS\"");
    assertThat(run(filter, export).getStatus()).isEqualTo(200);
    assertThat(run(filter, export).getStatus()).isEqualTo(429);
    for (int i = 0; i < 3; i++) {
      assertThat(run(filter, other).getStatus()).isEqualTo(200);
      assertThat(run(filter, getRegistrations).getStatus()).isEqualTo(200);
    }
  }

  @Test
  void httpsOnlyFilterRefusesPlainRemoteExportOnly() throws Exception {
    HttpsOnlyFilter filter = new HttpsOnlyFilter(true);
    MockHttpServletRequest remote = new MockHttpServletRequest("GET", "/api/export/registrations.xlsx");
    remote.setRemoteAddr("203.0.113.9");
    MockHttpServletRequest secure = new MockHttpServletRequest("GET", "/api/export/registrations.xlsx");
    secure.setRemoteAddr("203.0.113.9");
    secure.setSecure(true);
    MockHttpServletRequest local = new MockHttpServletRequest("GET", "/api/export/registrations.xlsx");
    local.setRemoteAddr("::1");
    MockHttpServletRequest form = new MockHttpServletRequest("GET", "/api/form-config");
    form.setRemoteAddr("203.0.113.9");

    MockHttpServletResponse refused = run(filter, remote);
    assertThat(refused.getStatus()).isEqualTo(403);
    assertThat(refused.getContentAsString()).contains("HTTPS_REQUIRED");
    assertThat(run(filter, secure).getStatus()).isEqualTo(200);
    assertThat(run(filter, local).getStatus()).isEqualTo(200);
    assertThat(run(filter, form).getStatus()).isEqualTo(200);
    assertThat(run(new HttpsOnlyFilter(false), remote).getStatus()).isEqualTo(200);
  }

  @Test
  void loopbackDetection() {
    assertThat(HttpsOnlyFilter.loopback("127.0.0.1")).isTrue();
    assertThat(HttpsOnlyFilter.loopback("127.10.0.2")).isTrue();
    assertThat(HttpsOnlyFilter.loopback("0:0:0:0:0:0:0:1")).isTrue();
    assertThat(HttpsOnlyFilter.loopback("10.0.0.1")).isFalse();
    assertThat(HttpsOnlyFilter.loopback("localhost")).isFalse();
    assertThat(HttpsOnlyFilter.loopback(null)).isFalse();
    assertThat(HttpsOnlyFilter.loopback("1:2:3")).isFalse();
  }

  @Test
  void sizeFilterRefusesDeclaredAndStreamedOversizedBodies() throws Exception {
    RequestSizeFilter filter = new RequestSizeFilter(10);
    MockHttpServletRequest declared = new MockHttpServletRequest("POST", "/api/registrations");
    declared.setContent(new byte[11]);

    MockHttpServletResponse refused = run(filter, declared);
    assertThat(refused.getStatus()).isEqualTo(413);
    assertThat(refused.getContentAsString()).contains("PAYLOAD_TOO_LARGE");

    AtomicReference<HttpServletRequest> passed = new AtomicReference<>();
    MockHttpServletRequest streamed =
        new MockHttpServletRequest("POST", "/api/registrations") {
          @Override
          public long getContentLengthLong() {
            return -1;
          }
        };
    streamed.setContent(new byte[11]);
    filter.doFilter(
        streamed, new MockHttpServletResponse(), (req, res) -> passed.set((HttpServletRequest) req));
    var in = passed.get().getInputStream();
    assertThat(passed.get().getInputStream()).isSameAs(in);
    assertThat(in.read(new byte[5], 0, 5)).isEqualTo(5);
    assertThat(in.read()).isZero();
    assertThat(in.isFinished()).isFalse();
    assertThat(in.isReady()).isTrue();
    assertThatThrownBy(() -> in.read(new byte[10], 0, 10)).isInstanceOf(PayloadTooLargeException.class);
  }

  @Test
  void sizeFilterLetsSmallBodiesThrough() throws Exception {
    RequestSizeFilter filter = new RequestSizeFilter(10);
    MockHttpServletRequest small = new MockHttpServletRequest("POST", "/api/registrations");
    small.setContent(new byte[10]);
    AtomicReference<HttpServletRequest> passed = new AtomicReference<>();

    filter.doFilter(small, new MockHttpServletResponse(), (req, res) -> passed.set((HttpServletRequest) req));

    assertThat(passed.get().getInputStream().readAllBytes()).hasSize(10);
    assertThat(passed.get().getInputStream().read()).isEqualTo(-1);
  }
}

package si.konferenca.registration.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.InOrder;
import si.konferenca.registration.domain.AcceptedRegistration;
import si.konferenca.registration.domain.Catalogs;
import si.konferenca.registration.domain.OptionCatalog;
import si.konferenca.registration.domain.RegistrationForm;
import si.konferenca.registration.domain.RegistrationType;
import si.konferenca.registration.domain.RegistrationValidator;
import si.konferenca.registration.domain.ValidationException;

class RegistrationServiceTest {

  private static final Instant NOW = Instant.parse("2026-10-11T08:00:00.123456Z");

  private final CaptchaVerifier captcha = mock(CaptchaVerifier.class);
  private final RegistrationStore store = mock(RegistrationStore.class);
  private final RegistrationRecorder recorder = mock(RegistrationRecorder.class);
  private final Notifier notifier = mock(Notifier.class);
  private final RegistrationService service =
      new RegistrationService(
          new RegistrationValidator(Catalogs.sample()),
          captcha,
          store,
          recorder,
          Clock.fixed(NOW, ZoneOffset.UTC),
          notifier);

  private static RegistrationForm form(String email) {
    return new RegistrationForm(
        "EXTERNAL", "Ana", "Novak", email, "IJS", null, null, null,
        List.of("ws-ai", "meal-lunch"), List.of("photos", "data"), " tok ");
  }

  @Test
  void storesThenNotifiesWithTheStoredCopy() {
    when(captcha.verify("tok", "1.2.3.4")).thenReturn(true);
    byte[] copy = {1, 2};
    when(recorder.record(any())).thenReturn(copy);

    AcceptedRegistration accepted = service.register(form("Ana@Example.si"), "1.2.3.4");

    assertThat(accepted.submittedAt()).isEqualTo(Instant.parse("2026-10-11T08:00:00.123Z"));
    assertThat(accepted.type()).isEqualTo(RegistrationType.EXTERNAL);
    assertThat(accepted.options()).extracting(AcceptedRegistration.SelectedOption::id).containsExactly("ws-ai", "meal-lunch");
    assertThat(accepted.consents()).extracting(AcceptedRegistration.GivenConsent::id).containsExactly("data", "photos");
    assertThat(accepted.consents()).allSatisfy(c -> assertThat(c.givenAt()).isEqualTo(accepted.submittedAt()));
    InOrder order = inOrder(store, recorder, notifier);
    order.verify(store).existsByNormalizedEmail("ana@example.si");
    order.verify(recorder).record(accepted);
    order.verify(notifier).sendParticipantConfirmation(accepted);
    order.verify(notifier).sendOrganizerNotification(accepted, copy);
  }

  @Test
  void invalidFormStopsBeforeCaptcha() {
    assertThatThrownBy(() -> service.register(form("bad"), "ip")).isInstanceOf(ValidationException.class);
    verifyNoInteractions(captcha, store, recorder, notifier);
  }

  @Test
  void rejectedCaptchaStopsBeforeStorage() {
    when(captcha.verify(anyString(), any())).thenReturn(false);

    assertThatThrownBy(() -> service.register(form("a@example.si"), "ip"))
        .isInstanceOf(CaptchaRejectedException.class);
    verifyNoInteractions(store, recorder, notifier);
  }

  @Test
  void duplicateEmailStopsBeforeStorage() {
    when(captcha.verify(anyString(), any())).thenReturn(true);
    when(store.existsByNormalizedEmail("a@example.si")).thenReturn(true);

    assertThatThrownBy(() -> service.register(form("a@example.si"), "ip"))
        .isInstanceOf(DuplicateEmailException.class);
    verify(recorder, never()).record(any());
    verifyNoInteractions(notifier);
  }

  @Test
  void failedStorageSendsNoEmail() {
    when(captcha.verify(anyString(), any())).thenReturn(true);
    when(recorder.record(any())).thenThrow(new IllegalStateException("db"));

    assertThatThrownBy(() -> service.register(form("a@example.si"), "ip")).isInstanceOf(IllegalStateException.class);
    verifyNoInteractions(notifier);
  }

  @Test
  void failedEmailsDoNotUndoTheRegistration() {
    when(captcha.verify(anyString(), any())).thenReturn(true);
    when(recorder.record(any())).thenReturn(new byte[0]);
    doThrow(new IllegalStateException("smtp")).when(notifier).sendParticipantConfirmation(any());
    doThrow(new IllegalStateException("smtp")).when(notifier).sendOrganizerNotification(any(), any());

    AcceptedRegistration accepted = service.register(form("a@example.si"), "ip");

    assertThat(accepted).isNotNull();
    verify(notifier).sendOrganizerNotification(any(), any());
